Migration mutation pattern:

```typescript
import { mutation } from './_generated/server';
import { v } from 'convex/values';
import { requireAuth } from './authHelpers';

export const migrateAnonymousData = mutation({
  args: { visitorId: v.string() },  // This is OK - user provides their own localStorage ID
  handler: async (ctx, { visitorId }) => {
    const userId = await requireAuth(ctx);  // Get authenticated user

    const results = { wordProgress: 0, userSongProgress: 0, ... };

    // Migrate wordProgress
    const wordProgressRecords = await ctx.db
      .query('wordProgress')
      .withIndex('by_visitor', q => q.eq('visitorId', visitorId))
      .collect();

    for (const record of wordProgressRecords) {
      // Create new record with userId
      await ctx.db.insert('wordProgress', {
        ...record,
        userId,
        visitorId: undefined,  // Clear old visitorId
      });
      results.wordProgress++;
    }

    // Repeat for other tables...

    return results;
  }
});
```

NOTE: It's OK to accept visitorId here because:
1. User can only migrate their OWN localStorage data (they provide the ID)
2. Data is copied TO their authenticated account (verified via ctx.auth)
3. This doesn't expose anyone else's data
